local function __andromeda_trace(proto,pc,opcode)
    local id=proto.id
    -- Resolved string/crypto helpers can execute millions of VM instructions.
    -- Keep their budget checks, but avoid formatting a trace row for every step.
    if id~=nil and not __andromeda_watched[id] then return end
    id=type(id)=="string" and id:match("^f%d+$") or "unknown"
    local fields={id,type(pc)=="number" and tostring(pc) or "_",
        type(opcode)=="number" and tostring(opcode) or "_"}
    for _,slot in ipairs({2,6,11,1,3,10}) do
        local operands=rawget(proto,slot)
        local value=type(operands)=="table" and rawget(operands,pc) or nil
        fields[#fields+1]=type(value)=="number" and tostring(value) or "_"
    end
    local row=table.concat(fields," ")
    if not __andromeda_seen[row] and #__andromeda_records<2004 then
        __andromeda_seen[row]=true
        __andromeda_records[#__andromeda_records+1]=row
    end
