    __andromeda_recent[__andromeda_recent_index]=row
    __andromeda_recent_count=math.min(128,__andromeda_recent_count+1)
end
local function __andromeda_recent_lines(limit)
    local lines={}
    local count=math.min(limit,__andromeda_recent_count)
    local first=(__andromeda_recent_index-count)%128+1
    for i=0,count-1 do lines[#lines+1]=__andromeda_recent[(first+i-1)%128+1] end
    return lines
end
local function __andromeda_contents()
    local parts={table.concat(__andromeda_records,"\n"),
        "STATE "..__andromeda_state,
        "LAST "..tostring(current_function or "initialization").." "..tostring(current_pc or 0),
        "XOR_FAST "..startup_fast_xor_calls.." XOR_SLOW "..startup_slow_xor_calls,
        "RECENT"}
    for _,row in ipairs(__andromeda_recent_lines(128)) do parts[#parts+1]=row end
