local function __andromeda_flush()
    __andromeda_last_attempt=read_startup_clock()
    if type(writefile)~="function" then
        __andromeda_file_status="unavailable"
        __andromeda_note("TRACE NOT SAVED: writefile unavailable; console export remains available")
        return false
    end
    local contents=__andromeda_contents()
    local paths=__andromeda_path and {__andromeda_path} or __andromeda_paths
    local detail="no writable path"
    for _,path in ipairs(paths) do
        local ok,result=pcall(writefile,path,contents)
        if ok and result~=false then
            if type(readfile)=="function" then
                local read_ok,saved=pcall(readfile,path)
                if read_ok and saved==contents then
                    __andromeda_path=path
                    __andromeda_file_status="verified"
                    __andromeda_note("TRACE SAVED AND VERIFIED: API-relative path "..path)
                    return true
                end
                detail="read-back did not match"
            else
                __andromeda_path=path
                __andromeda_file_status="unverified"
                __andromeda_note("TRACE WRITE UNVERIFIED: "..path.."; console export remains available")
                return false
            end
        else
            detail=tostring(result)
        end
    end
    __andromeda_path=nil
    __andromeda_file_status="failed"
    __andromeda_note("TRACE NOT SAVED: "..detail.."; use the console export below")
    return false
end
