    startup_notice("TRACE_CONSOLE_BEGIN")
    startup_notice(__andromeda_records[1])
    startup_notice(__andromeda_records[4])
    startup_notice("STATE "..__andromeda_state.." LAST "..startup_location())
    startup_notice("XOR_FAST "..startup_fast_xor_calls.." XOR_SLOW "..startup_slow_xor_calls)
    startup_notice("FILE_STATUS "..__andromeda_file_status..
        (__andromeda_path and " API_PATH "..__andromeda_path or ""))
    if page then
        local pages=math.max(1,math.ceil(#__andromeda_records/64))
        page=math.max(1,math.min(pages,math.floor(page)))
        startup_notice("PAGE "..page.."/"..pages)
        for i=(page-1)*64+1,math.min(page*64,#__andromeda_records) do
            startup_notice(__andromeda_records[i])
        end
    else
        startup_notice("RECENT_TARGET_STEPS")
        for _,row in ipairs(__andromeda_recent_lines(32)) do startup_notice(row) end
    end
    startup_notice("TRACE_CONSOLE_END")
end
startup_on_checkpoint=function()
