    if now and __andromeda_last_attempt and now-__andromeda_last_attempt<500 then return end
    if not now and __andromeda_save_counter%60~=0 then return end
    __andromeda_flush()
end
startup_on_finish=function(state)
    __andromeda_state=state
    local ok,err=pcall(__andromeda_flush)
    if not ok then
        __andromeda_file_status="error"
        startup_notice("TRACE SAVE CALLBACK FAILED: "..tostring(err))
    end
    -- This export is unconditional: failed file I/O cannot hide the last steps.
    __andromeda_dump()
end
if type(client)=="table" and type(client.set_event_callback)=="function" then
    local ok,err=pcall(client.set_event_callback,"console_input",function(text)
        if type(text)~="string" then return end
        if text:match("^%s*andromeda_trace_dump%s*$") then
            __andromeda_dump()
            return true
        end
        local page=text:match("^%s*andromeda_trace_dump%s+(%d+)%s*$")
        if page then __andromeda_dump(tonumber(page));return true end
    end)
    if not ok then startup_notice("Manual console export unavailable: "..tostring(err)) end
end
local __andromeda_initial_ok,__andromeda_initial_error=pcall(__andromeda_flush)
if not __andromeda_initial_ok then
    __andromeda_file_status="error"
    startup_notice("Initial trace save failed: "..tostring(__andromeda_initial_error))
end


